import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_3x3_bf16(torch::Tensor x, torch::Tensor w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

// Cooperative tiled 3x3 conv (stride=1, pad=0), bf16 in/out, fp32 accumulate.
// C_in = 3, C_out = 32, K = 3x3. Each block computes a 16x16 output tile
// for ALL 32 output channels of one image. The input tile (18x18x3) and all
// weights are staged in shared memory cooperatively; each thread then computes
// weights are staged in shared memory cooperatively; each thread then computes
// TWO output pixels (register-blocked rows r and r+8) across all 32 output
// channels so each shared-memory weight load feeds two FMAs. Threads in a warp
__global__ __launch_bounds__(256)
void conv2d_3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ Wt,
    __nv_bfloat16* __restrict__ Y,
    int H, int W, int Hout, int Wout)
{
  using namespace cute;

  constexpr int CI      = 3;
  constexpr int CO      = 16;   // split 32 output channels across two CTAs to halve accumulator registers
  constexpr int K       = 3;
  constexpr int TH      = 16;
  constexpr int TW      = 32;
  constexpr int IH      = TH + K - 1;   // 10
  constexpr int IW      = TW + K - 1;   // 34
  constexpr int THREADS = 256;

  const int n   = blockIdx.z >> 1;   // z packs (image, channel-half)
  const int oh0 = blockIdx.y * TH;
  const int ow0 = blockIdx.x * TW;
  const int tid = threadIdx.x;

  // Global tensors for this image, described with CUTE layouts
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * CI * H * W),
                        make_shape(Int<CI>{}, H, W),
                        make_stride((int64_t)H * W, (int64_t)W, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * (2 * CO) * Hout * Wout),
                        make_shape(Int<32>{}, Hout, Wout),
                        make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(Int<32>{}, Int<CI * K * K>{}),
                        make_stride(Int<CI * K * K>{}, Int<1>{}));

  // Shared memory (stored as fp32 for cheap FMAs)
  __shared__ float sX_raw[CI * IH * IW];
  __shared__ float sW_raw[CO * CI * K * K];

  auto sX = make_tensor(make_smem_ptr(sX_raw),
                        make_shape(Int<CI>{}, Int<IH>{}, Int<IW>{}));
  auto sW = make_tensor(make_smem_ptr(sW_raw),
                        make_shape(Int<CO>{}, Int<CI * K * K>{}));

  // Cooperative vectorized load of the weights (864 bf16 = 432 bf16x2), converted to fp32
  constexpr int W_ELEMS = CO * CI * K * K;
  if ((reinterpret_cast<size_t>(Wt) & 3) == 0) {
    const __nv_bfloat162* w2 = reinterpret_cast<const __nv_bfloat162*>(Wt + ((blockIdx.z & 1) * CO) * (CI * K * K));
    for (int idx = tid; idx < W_ELEMS / 2; idx += THREADS) {
      const __nv_bfloat162 v = w2[idx];
      const int e0  = 2 * idx;
      const int oc0 = e0 / (CI * K * K);
      const int k0  = e0 - oc0 * (CI * K * K);
      sW(oc0, k0) = __bfloat162float(v.x);
      const int e1  = e0 + 1;
      const int oc1 = e1 / (CI * K * K);
      const int k1  = e1 - oc1 * (CI * K * K);
      sW(oc1, k1) = __bfloat162float(v.y);
    }
  } else {
    for (int idx = tid; idx < W_ELEMS; idx += THREADS) {
      int oc = idx / (CI * K * K);
      int k  = idx - oc * (CI * K * K);
      sW(oc, k) = __bfloat162float(mW(((blockIdx.z & 1) * CO) + oc, k));
    }
  }

  // Cooperative load of the input tile (halo included), zero-filled at borders.
  // Use aligned bf16x2 row loads when the layout guarantees even element offsets.
  const __nv_bfloat16* xbase = X + (int64_t)n * CI * H * W;
  const bool vec_in_ok = ((reinterpret_cast<size_t>(xbase) & 3) == 0) && ((W & 1) == 0);
  if (vec_in_ok) {
    constexpr int PAIRS_PER_ROW = IW / 2;
    for (int idx = tid; idx < CI * IH * PAIRS_PER_ROW; idx += THREADS) {
      const int pair = idx % PAIRS_PER_ROW;
      const int row  = idx / PAIRS_PER_ROW;
      const int ic   = row / IH;
      const int r    = row - ic * IH;
      const int c    = 2 * pair;
      const int ih   = oh0 + r;
      const int iw   = ow0 + c;
      float v0 = 0.0f;
      float v1 = 0.0f;
      if (ih < H) {
        const int64_t off = ((int64_t)ic * H + ih) * W + iw;
        if (iw + 1 < W) {
          const __nv_bfloat162 v = *reinterpret_cast<const __nv_bfloat162*>(xbase + off);
          v0 = __bfloat162float(v.x);
          v1 = __bfloat162float(v.y);
        } else {
          if (iw < W)     v0 = __bfloat162float(xbase[off]);
          if (iw + 1 < W) v1 = __bfloat162float(xbase[off + 1]);
        }
      }
      sX(ic, r, c) = v0;
      sX(ic, r, c + 1) = v1;
    }
  } else {
    for (int idx = tid; idx < CI * IH * IW; idx += THREADS) {
      int ic  = idx / (IH * IW);
      int rem = idx - ic * (IH * IW);
      int r   = rem / IW;
      int c   = rem - r * IW;
      int ih  = oh0 + r;
      int iw  = ow0 + c;
      float v = 0.0f;
      if (ih < H && iw < W) {
        v = __bfloat162float(mX(ic, ih, iw));
      }
      sX(ic, r, c) = v;
    }
  }
  __syncthreads();

  // Each thread owns two output pixels of the 16x32 tile (rows r and r+8),
  // register-blocking the spatial dimension so each sW load feeds 2 FMAs
  const int r   = tid >> 5;   // 0..7
  const int c   = tid & 31;   // 0..31
  const int oh  = oh0 + r;
  const int oh2 = oh0 + r + 8;
  const int ow  = ow0 + c;
  const bool valid0 = (oh  < Hout) && (ow < Wout);
  const bool valid1 = (oh2 < Hout) && (ow < Wout);
  if (valid0 || valid1) {
    float acc0[CO];
    float acc1[CO];
    #pragma unroll
    for (int oc = 0; oc < CO; ++oc) { acc0[oc] = 0.0f; acc1[oc] = 0.0f; }
    #pragma unroll
    for (int ic = 0; ic < CI; ++ic) {
      #pragma unroll
      for (int kh = 0; kh < K; ++kh) {
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
          const float xv0 = sX(ic, r + kh, c + kw);
          const float xv1 = sX(ic, r + 8 + kh, c + kw);
          const int k     = (ic * K + kh) * K + kw;
          #pragma unroll
          for (int oc = 0; oc < CO; ++oc) {
            const float wv = sW(oc, k);
            acc0[oc] = fmaf(xv0, wv, acc0[oc]);
            acc1[oc] = fmaf(xv1, wv, acc1[oc]);
          }
        }
      }
    }
    // Coalesced stores: consecutive threads write consecutive `ow`
    #pragma unroll
    for (int oc = 0; oc < CO; ++oc) {
      if (valid0) mY(((blockIdx.z & 1) * CO) + oc, oh,  ow) = __float2bfloat16(acc0[oc]);
      if (valid1) mY(((blockIdx.z & 1) * CO) + oc, oh2, ow) = __float2bfloat16(acc1[oc]);
    }
  }
}

torch::Tensor conv2d_3x3_bf16(torch::Tensor x, torch::Tensor w) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(w.scalar_type() == at::kBFloat16, "w must be bfloat16");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C_in, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C_out, C_in, 3, 3]");
  TORCH_CHECK(x.size(1) == 3, "expect C_in == 3");
  TORCH_CHECK(w.size(0) == 32 && w.size(1) == 3 &&
              w.size(2) == 3 && w.size(3) == 3,
              "expect w shape [32, 3, 3, 3]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N = x_c.size(0);
  const int64_t H = x_c.size(2);
  const int64_t W = x_c.size(3);
  TORCH_CHECK(H >= 3 && W >= 3, "spatial dims must be >= kernel size");

  const int64_t Hout = H - 2;
  const int64_t Wout = W - 2;

  auto y = torch::empty({N, 32, Hout, Wout}, x_c.options());

  constexpr int TH = 16;
  constexpr int TW = 32;
  dim3 block(256);
  dim3 grid((unsigned)((Wout + TW - 1) / TW),
            (unsigned)((Hout + TH - 1) / TH),
            (unsigned)(2 * N));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_3x3_bf16_kernel<<<grid, block, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __nv_bfloat16*>(w_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>()),
      (int)H, (int)W, (int)Hout, (int)Wout);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_3x3_bf16_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_3x3_bf16_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_3x3_bf16"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Conv2d(3, 32, kernel_size=3, stride=1, padding=0, bias=False) in bfloat16,
    computed entirely by a single custom cooperative tiled CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv2d module purely as the parameter holder so that
        # initialization and state_dict layout match the reference model.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3,
                               bias=False, dtype=torch.bfloat16)
        self._ext = conv2d_ext

    def forward(self, x):
        return self._ext.conv2d_3x3_bf16(x.contiguous(), self.conv1.weight.contiguous())

