      const int oc0 = e0 / (CI * K * K);
      const int k0  = e0 - oc0 * (CI * K * K);
      sW(oc0, k0) = __bfloat162float(v.x);
      const int e1  = e0 + 1;
      const int oc1 = e1 / (CI * K * K);
      const int k1  = e1 - oc1 * (CI * K * K);
      sW(oc1, k1) = __bfloat162float(v.y);
