  } else {
    for (int idx = tid; idx < W_ELEMS; idx += THREADS) {
      int oc = idx / (CI * K * K);
      int k  = idx - oc * (CI * K * K);
      sW(oc, k) = __bfloat162float(mW(((blockIdx.z & 1) * CO) + oc, k));
